sp_widget.client_script:
api.controller = function($location) {

    var c = this;


    /* =====================================================
       VARIABLES
    ====================================================== */

    c.loading = false;

    c.paymentFound = false;

    c.payment = {};

    c.errorMessage = "";



    /* =====================================================
       LOAD PAYMENT
    ====================================================== */

    c.loadPayment = function() {

        c.loading = true;

        c.paymentFound = false;

        c.errorMessage = "";


        var params =
            $location.search();


        var sysId =
            params.sys_id || "";


        var claimNumber =
            params.claim_number || "";


        /*
         * Payment page must receive
         * claim information.
         */

        if (!sysId && !claimNumber) {

            c.loading = false;

            c.errorMessage =
                "Claim information is missing.";

            return;
        }


        c.server.get({

            action:
                "get_payment",

            sys_id:
                sysId,

            claim_number:
                claimNumber

        }).then(function(response) {

            c.loading = false;


            if (
                response.data.success === true &&
                response.data.paymentFound === true
            ) {

                c.paymentFound = true;

                c.payment =
                    response.data.payment;

            }

            else {

                c.paymentFound = false;

                c.errorMessage =
                    response.data.message ||
                    "Unable to load payment details.";

            }

        }, function() {

            c.loading = false;

            c.paymentFound = false;

            c.errorMessage =
                "Unable to load payment details.";

        });

    };



    /* =====================================================
       BACK TO TRACK CLAIM
    ====================================================== */

    c.goBackToTrack = function() {

        if (
            c.payment &&
            c.payment.sys_id
        ) {

            $location.search({

                id:
                    "track_claim",

                sys_id:
                    c.payment.sys_id

            });

        }

        else {

            $location.search({

                id:
                    "track_claim"

            });

        }

    };



    /* =====================================================
       HOME
    ====================================================== */

    c.goHome = function() {

        $location.search({

            id:
                "claim_home"

        });

    };



    /* =====================================================
       REFRESH
    ====================================================== */

    c.refreshPayment = function() {

        c.loadPayment();

    };



    /* =====================================================
       PAYMENT STATUS CLASS
    ====================================================== */

    c.getPaymentStatusClass =
        function(status) {

        if (!status) {

            return "payment-pending";

        }


        var value =
            String(status)
                .toLowerCase()
                .trim();


        if (value == "paid") {

            return "payment-paid";

        }


        if (value == "processing") {

            return "payment-processing";

        }


        if (value == "failed") {

            return "payment-failed";

        }


        return "payment-pending";

    };



    /* =====================================================
       PAYMENT TIMELINE
    ====================================================== */

    c.getStepClass = function(step) {

        var status =
            String(
                c.payment.payment_status ||
                "Pending"
            )
            .toLowerCase()
            .trim();


        if (status == "pending") {

            if (step == 1) {

                return "completed";

            }

            return "";

        }


        if (status == "processing") {

            if (step <= 2) {

                return "completed";

            }

            return "";

        }


        if (status == "paid") {

            return "completed";

        }


        if (status == "failed") {

            if (step == 1) {

                return "completed";

            }

            if (step == 2) {

                return "failed";

            }

            return "";

        }


        return "";

    };



    /* =====================================================
       INITIAL LOAD
    ====================================================== */

    c.loadPayment();

};

sp_widget.css:
.payment-page {
    max-width: 1000px;
    margin: 0 auto;
    padding: 35px 25px 60px;
    font-family: Arial, sans-serif;
    color: #123b63;
}


/* ==========================================
   HEADER
========================================== */

.payment-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    border-bottom: 1px solid #d9e5ef;
    padding-bottom: 22px;
    margin-bottom: 25px;
}

.payment-badge {
    display: inline-block;
    background: #e8f4ff;
    color: #1476c9;
    padding: 6px 11px;
    border-radius: 20px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .5px;
}

.payment-header h1 {
    margin: 8px 0 5px;
    font-size: 30px;
    font-weight: 800;
}

.payment-header p {
    margin: 0;
    color: #71869a;
    font-size: 13px;
}

.back-track-btn {
    border: 1px solid #1388d4;
    background: white;
    color: #0877bd;
    padding: 10px 18px;
    border-radius: 8px;
    font-weight: 700;
    cursor: pointer;
}

.back-track-btn:hover {
    background: #eef8ff;
}


/* ==========================================
   LOADING
========================================== */

.payment-loading {
    background: white;
    border-radius: 14px;
    padding: 55px;
    text-align: center;
    box-shadow: 0 5px 20px rgba(30, 80, 120, .08);
}

.payment-spinner {
    width: 32px;
    height: 32px;
    margin: auto;
    border: 4px solid #dcecf8;
    border-top: 4px solid #1476d4;
    border-radius: 50%;
    animation: paymentSpin 1s linear infinite;
}

.payment-loading p {
    margin-top: 15px;
    color: #6f8497;
}

@keyframes paymentSpin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}


/* ==========================================
   ERROR
========================================== */

.payment-error-card {
    background: white;
    border-radius: 15px;
    padding: 50px;
    text-align: center;
    box-shadow: 0 5px 20px rgba(30, 80, 120, .08);
}

.error-icon {
    width: 42px;
    height: 42px;
    margin: auto;
    border-radius: 50%;
    background: #ffe9e9;
    color: #e53935;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    font-size: 22px;
}

.payment-error-card h2 {
    margin: 15px 0 8px;
    color: #173b5f;
}

.payment-error-card p {
    color: #7b8c9c;
}

.try-again-btn {
    border: 1px solid #0a7bd7;
    background: white;
    color: #0875c4;
    padding: 9px 18px;
    border-radius: 7px;
    font-weight: 700;
    cursor: pointer;
}


/* ==========================================
   CLAIM HEADER
========================================== */

.claim-payment-card {
    background: white;
    border-radius: 14px;
    padding: 22px 25px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 5px 20px rgba(30, 80, 120, .08);
    margin-bottom: 18px;
}

.field-label {
    display: block;
    font-size: 11px;
    color: #7a8da0;
    margin-bottom: 5px;
}

.claim-number {
    font-size: 22px;
    font-weight: 800;
    color: #0874c1;
}


/* ==========================================
   STATUS BADGE
========================================== */

.payment-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 13px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 800;
}

.status-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
}

.payment-pending {
    background: #fff5d9;
    color: #a76d00;
}

.payment-processing {
    background: #e9f4ff;
    color: #1472c5;
}

.payment-paid {
    background: #e7f8ef;
    color: #16834e;
}

.payment-failed {
    background: #ffe8e8;
    color: #c62f2f;
}


/* ==========================================
   CARD
========================================== */

.payment-card {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 18px;
    box-shadow: 0 5px 20px rgba(30, 80, 120, .08);
}

.card-title {
    display: flex;
    align-items: center;
    gap: 10px;
    border-bottom: 1px solid #e4edf4;
    padding-bottom: 15px;
    margin-bottom: 20px;
}

.card-title h2 {
    margin: 0;
    font-size: 17px;
    color: #19476d;
}

.title-icon {
    font-size: 18px;
}


/* ==========================================
   SETTLEMENT GRID
========================================== */

.payment-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 22px 40px;
}

.payment-item strong {
    color: #1e4261;
    font-size: 13px;
}

.full-width {
    grid-column: 1 / -1;
}

.payment-reference {
    display: inline-block;
    background: #edf6ff;
    color: #0873c0 !important;
    padding: 8px 12px;
    border-radius: 6px;
    letter-spacing: .4px;
}


/* ==========================================
   PAYMENT MESSAGE
========================================== */

.status-message {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 20px;
    border-radius: 10px;
}

.status-message h3 {
    margin: 0 0 6px;
    font-size: 16px;
}

.status-message p {
    margin: 0;
    font-size: 12px;
    color: #667b8f;
}

.pending-message {
    background: #fff9e9;
}

.processing-message {
    background: #edf7ff;
}

.paid-message {
    background: #ebf9f1;
}

.failed-message {
    background: #fff0f0;
}

.status-large-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: white;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 22px;
}


/* ==========================================
   TIMELINE
========================================== */

.payment-timeline {
    position: relative;
    padding-left: 10px;
}

.payment-step {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    position: relative;
    padding-bottom: 28px;
    opacity: .45;
}

.payment-step:last-child {
    padding-bottom: 0;
}

.payment-step.completed {
    opacity: 1;
}

.payment-step.failed {
    opacity: 1;
}

.step-number {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: #edf1f5;
    color: #718394;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 800;
    flex-shrink: 0;
}

.payment-step.completed .step-number {
    background: #1679d2;
    color: white;
}

.payment-step.failed .step-number {
    background: #dc3b3b;
    color: white;
}

.step-content h3 {
    margin: 2px 0 4px;
    font-size: 13px;
    color: #244a68;
}

.step-content p {
    margin: 0;
    font-size: 11px;
    color: #7a8d9e;
}


/* ==========================================
   BUTTONS
========================================== */

.payment-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
    margin-top: 25px;
}

.refresh-payment-btn,
.home-payment-btn {
    padding: 10px 20px;
    border-radius: 8px;
    font-weight: 700;
    cursor: pointer;
}

.refresh-payment-btn {
    border: 1px solid #1680d2;
    background: white;
    color: #0873c0;
}

.home-payment-btn {
    border: none;
    background: #0876d1;
    color: white;
}

.refresh-payment-btn:hover {
    background: #eef8ff;
}

.home-payment-btn:hover {
    background: #075eaa;
}


/* ==========================================
   MOBILE
========================================== */

@media (max-width: 700px) {

    .payment-page {
        padding: 20px 15px;
    }

    .payment-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .payment-grid {
        grid-template-columns: 1fr;
    }

    .full-width {
        grid-column: auto;
    }

    .claim-payment-card {
        flex-direction: column;
        align-items: flex-start;
        gap: 15px;
    }

    .payment-actions {
        flex-direction: column;
    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.paymentFound = false;
    data.payment = {};
    data.message = "";

    if (!input) {
        return;
    }


    /* =====================================================
       GET PAYMENT DETAILS
    ====================================================== */

    if (input.action == "get_payment") {

        var sysId =
            String(
                input.sys_id || ""
            ).trim();


        var claimNumber =
            String(
                input.claim_number || ""
            ).trim();


        /*
         * Either sys_id OR claim number
         * is required.
         */

        if (!sysId && !claimNumber) {

            data.message =
                "Claim information is missing.";

            return;
        }


        var claim =
            new GlideRecord(
                "x_snc_insurance_0_claim"
            );


        /* =================================================
           SEARCH BY SYS_ID
        ================================================== */

        if (sysId) {

            if (!claim.get(sysId)) {

                data.message =
                    "Claim was not found.";

                return;
            }

        }


        /* =================================================
           SEARCH BY CLAIM NUMBER
        ================================================== */

        else {

            claim.addQuery(
                "claim_number",
                claimNumber
            );

            claim.setLimit(1);

            claim.query();


            if (!claim.next()) {

                data.message =
                    "No claim found with claim number: " +
                    claimNumber;

                return;
            }

        }


        /* =================================================
           CLAIM DATA
        ================================================== */

        var actualClaimNumber =
            claim.getValue(
                "claim_number"
            ) || "";


        var claimType =
            claim.getDisplayValue(
                "claim_type"
            ) || "Motor";


        var policyNumber =
            claim.getDisplayValue(
                "policy_number"
            ) || "POL1001";


        var claimAmount =
            claim.getDisplayValue(
                "claim_amount"
            ) || "₹0";


        var recommendedPayout =
            claim.getDisplayValue(
                "recommended_payout"
            ) || "₹0";


        var finalPayout =
            claim.getDisplayValue(
                "final_payout"
            ) || "₹0";


        /* =================================================
           PAYMENT STATUS
        ================================================== */

        var paymentStatus =
            claim.getDisplayValue(
                "payment_status"
            );


        if (!paymentStatus) {

            paymentStatus =
                "Pending";

        }


        /* =================================================
           PAYMENT REFERENCE
        ================================================== */

        var paymentReference =
            "PAY-" +
            actualClaimNumber +
            "-001";


        /* =================================================
           RETURN DATA
        ================================================== */

        data.payment = {

            sys_id:
                claim.getUniqueValue(),

            claim_number:
                actualClaimNumber,

            claim_type:
                claimType,

            policy_number:
                policyNumber,

            claim_amount:
                claimAmount,

            recommended_payout:
                recommendedPayout,

            final_payout:
                finalPayout,

            payment_status:
                paymentStatus,

            payment_reference:
                paymentReference

        };


        data.success = true;

        data.paymentFound = true;

        return;
    }

})();
